// Validate the complete, version-pinned site-build contract before persistence.
const contract = $json.body ?? $json;
const errors = [];
const requiredArtifacts = ['site_architecture','content_plan','design_plan','wordpress_plan','execution_plan'];

if (contract.contract_version !== '1.0') errors.push(`unsupported contract_version: ${contract.contract_version}`);
if (!contract.request_id) errors.push('missing request_id');
if (!contract.business?.name) errors.push('missing business.name');
if (!contract.business?.type) errors.push('missing business.type');
if (!contract.execution_mode || !['dry_run','apply'].includes(contract.execution_mode)) errors.push('execution_mode must be dry_run or apply');
if (!contract.target_site?.site_id) errors.push('missing target_site.site_id');
if (contract.constraints?.theme !== 'astra') errors.push('constraints.theme must be astra');
if (contract.constraints?.builder !== 'elementor') errors.push('constraints.builder must be elementor');
if (contract.constraints?.publish !== false) errors.push('constraints.publish must be false');
if (!['free','pro'].includes(contract.constraints?.elementor_level)) errors.push('constraints.elementor_level must be free or pro');
if (!['auto','manual'].includes(contract.kit_selection?.mode)) errors.push('kit_selection.mode must be auto or manual');
if (contract.kit_selection?.mode === 'manual' && !contract.kit_selection?.kit_id) errors.push('manual kit selection requires kit_id');
for (const key of requiredArtifacts) {
  const version = contract.approved_artifact_versions?.[key];
  if (!Number.isInteger(version) || version < 1) errors.push(`approved_artifact_versions.${key} must be an integer >= 1`);
}

return [{ json: { contract, valid: errors.length === 0, errors } }];

// Task 2 (part 1): detect missing critical information. A plumber/local
// business contract without any way to be reached is not buildable.
const { contract } = $json;
const missing = [];
if (!contract.business.coordinates?.phone && !contract.business.coordinates?.email) {
  missing.push('business.coordinates.phone or business.coordinates.email');
}
return [{ json: { contract, missing_information: missing } }];

// Unmitigated high/critical risk forces dry_run before persistence.
const { contract, missing_information } = $json;
const severityOrder = { low: 0, medium: 1, high: 2, critical: 3 };
const risks = contract.risks || [];
const hasUnmitigatedHighRisk = risks.some(r => !r.mitigated && severityOrder[r.severity] >= severityOrder.high);
const forceDryRun = missing_information.length > 0 || hasUnmitigatedHighRisk;
const executionMode = forceDryRun ? 'dry_run' : contract.execution_mode;
const buildState = missing_information.length > 0 ? 'needs_input' : 'awaiting_staging_approval';
const reason = missing_information.length > 0 ? 'missing critical information: ' + missing_information.join(', ') : 'contract complete, awaiting human staging approval';
return [{ json: {
  request_id: contract.request_id,
  contract_version: contract.contract_version,
  business: contract.business,
  site: contract.site,
  execution_mode: executionMode,
  approved_artifact_versions: contract.approved_artifact_versions,
  target_site: contract.target_site,
  kit_selection: contract.kit_selection,
  constraints: contract.constraints,
  missing_information,
  risks,
  build_state: buildState,
  actor: 'intake-workflow',
  reason
} }];

// Task 4 guard, made visible: only a request currently
// awaiting_staging_approval can move to ready_for_staging. Everything
// else is a policy violation we report instead of silently accepting.
const approvalRequest = $('Approve Staging Webhook').first().json.body;
const current = $json.contract.build_state;
return [{ json: {
  request_id: approvalRequest.request_id,
  actor: approvalRequest.actor,
  reason: approvalRequest.reason,
  current_state: current,
  can_approve: current === 'awaiting_staging_approval'
} }];
